/* Deterministic dimensioned concept sheets. All geometry is authored in mm. */
window.AtlasCad = (() => {
  let role = 'guardian', language = 'vi', kit = {}, view = 'front';
  const $ = id => document.getElementById(id);
  const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const specs = {
    guardian: { grip: [250, 250], cavity: [90, 60], notes: ['EVA mặt 5 mm + vòng 10 mm + tấm sau 5 mm; khoảng trống còn lại là bao lắp ráp.', 'Quai rộng 2,5 cm; tâm hai quai cách 15 cm ở mẫu chuẩn. Cần thử người thật.'], en: ['5 mm EVA face + 10 mm ring + 5 mm rear plate; remaining depth is an assembly envelope.', '2.5 cm straps; 15 cm centre spacing on the reference mock-up. Fit-test first.'] },
    warrior: { grip: [55, 545], cavity: [34, 85], notes: ['Vùng lưỡi cao 45 cm, tay cầm + chắn tay 20 cm.', 'Khoang chỉ là bao dự kiến; đo board và đầu nối trước khi làm cán.'], en: ['45 cm blade zone; 20 cm guard and grip zone.', 'Cavity is provisional; measure board and connectors before making the grip.'] },
    archer: { grip: [215, 450], cavity: [45, 90], notes: ['Cánh recurve đối xứng; dây trang trí ở x = 39 cm, không có mũi tên.', 'Bộ Hall / slider cần test riêng; không kéo dây để tích năng lượng.'], en: ['Symmetric recurve limbs; cosmetic string at x = 39 cm, no arrow.', 'Hall/slider requires separate proof; never draw to store launch energy.'] },
    assassin: { grip: [37.5, 265], cavity: [28, 60], notes: ['Lưỡi 21 cm; cán + chắn tay 11 cm; chỉ một dao có điện tử.', 'Khoang nhỏ có thể không vừa DevKit: thử bao board trước, chuyển core sang cổ tay nếu không vừa.'], en: ['21 cm blade; 11 cm guard and grip; one active dagger only.', 'A DevKit may not fit: check its envelope first; move the core to a wrist unit if needed.'] },
    mage: { grip: [70, 850], cavity: [35, 90], notes: ['Quả cầu Ø14 cm, thân tới đầu dưới tổng 110 cm.', 'Core dưới tay cầm; đầu trên/dưới mềm và tháo bảo trì được.'], en: ['14 cm orb diameter; overall length to lower tip 110 cm.', 'Core below grip; padded ends and serviceable cover.'] },
    boss: { grip: [180, 980], cavity: [34, 110], notes: ['Lưỡi đại kiếm 9 × 82 cm, EVA rỗng quanh lõi PVC nhẹ; mũi bo tròn, không dùng khối cứng.', 'Chắn tay 36 cm; ESP32 nằm trong tay cầm 4 × 25 cm — đo board thật trước khi khoét. Giáp Boss là bộ riêng.'], en: ['Greatsword blade 9 × 82 cm: hollow EVA over a light PVC spine; rounded tip, no solid rigid block.', '36 cm guard; ESP32 sits in the 4 × 25 cm grip — measure the real board before cutting. Boss armour is a separate assembly.'] }
  };
  const cm = mm => Number((mm / 10).toFixed(2));
  function geometry(r, w, h) {
    if (r === 'guardian') return `<circle cx="250" cy="250" r="250"/><circle class="detail" cx="250" cy="250" r="230"/><circle class="detail" cx="250" cy="250" r="220"/>`;
    if (r === 'warrior' || r === 'assassin') { const end = r === 'warrior' ? 450 : 210; return `<path d="M${w/2-8} 8 Q${w/2-8} 0 ${w/2} 0 Q${w/2+8} 0 ${w/2+8} 8 L${w*.7} 25 L${w*.78} ${end} L${w} ${end+12} L${w} ${end+32} L${w*.7} ${end+32} L${w*.7} ${h-15} Q${w/2} ${h+10} ${w*.3} ${h-15} L${w*.3} ${end+32} L0 ${end+32} L0 ${end+12} L${w*.22} ${end} L${w*.3} 25 Z"/>`; }
    if (r === 'archer') return `<path d="M390 0 C340 25 145 60 100 210 C50 330 205 365 205 410 L205 490 C205 535 50 570 100 690 C145 840 340 875 390 900 L405 880 C345 855 185 790 135 680 C95 575 240 535 240 490 L240 410 C240 365 95 325 135 220 C185 110 345 45 405 20 Z"/><path class="string" d="M390 0 L390 900"/><rect class="detail" x="190" y="390" width="65" height="120" rx="16"/>`;
    if (r === 'mage') return `<circle cx="70" cy="70" r="70"/><rect x="50" y="130" width="40" height="970" rx="20"/>`;
    return `<path d="M180 0 Q210 18 225 60 L225 820 L135 820 L135 60 Q150 18 180 0 Z"/><path class="detail" d="M180 70 V800"/><rect x="0" y="820" width="360" height="40" rx="14"/><rect x="160" y="860" width="40" height="250" rx="20"/><circle cx="180" cy="1120" r="30"/>`;
  }
  function svg() {
    const d = window.ATLAS_PROP_MANIFESTS[role].dimensionsMm, s = specs[role], vi = language === 'vi';
    const w = view === 'side' ? d.depth : d.width, h = d.height;
    const scale = Math.min(660 / h, 600 / w), x = 130, y = 145, W = w * scale, H = h * scale;
    const label = (a,b,t,anchor='middle') => `<text x="${a}" y="${b}" text-anchor="${anchor}">${esc(t)}</text>`;
    const line = (a,b,c,e,cls='dim') => `<line class="${cls}" x1="${a}" y1="${b}" x2="${c}" y2="${e}"/>`;
    const grid = $('cadGrid').checked ? `<rect x="${x}" y="${y}" width="${W}" height="${H}" fill="url(#cad-grid)"/>` : '';
    const body = view === 'side' ? `<rect x="0" y="0" width="${w}" height="${h}" rx="${Math.min(w/3,20)}"/><path class="detail" d="M${w*.35} 0 V${h}"/>` : geometry(role,w,h);
    const [cx,cy] = s.grip, [cw,ch] = s.cavity;
    const rear = view === 'rear' ? `<rect class="cavity" x="${cx-cw/2}" y="${cy-ch/2}" width="${cw}" height="${ch}" rx="8"/><circle class="sensor" cx="${cx}" cy="${cy-ch/2-18}" r="9"/>` + (role === 'guardian' ? `<rect class="strap" x="150" y="162.5" width="200" height="25" rx="8"/><rect class="strap" x="150" y="312.5" width="200" height="25" rx="8"/>` : '') : '';
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1080 950" role="img" aria-label="${esc(kit.name)} dimensioned concept sheet"><defs><pattern id="cad-grid" width="${10*scale}" height="${10*scale}" patternUnits="userSpaceOnUse"><path d="M${10*scale} 0 H0 V${10*scale}" fill="none" stroke="#d9e4e7" stroke-width=".5"/></pattern><marker id="cad-arrow" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 Z" fill="#256c84"/></marker></defs><style>text{font:16px sans-serif;fill:#203d49}.shape{fill:none;stroke:#172d38;stroke-width:${1.7/scale}}.detail{stroke:#448799;stroke-width:${1/scale};fill:none}.dim{stroke:#256c84;stroke-width:1.2;marker-start:url(#cad-arrow);marker-end:url(#cad-arrow)}.ext{stroke:#879ba4;stroke-width:.8}.centre{stroke:#dc7245;stroke-dasharray:10 4 2 4;stroke-width:1}.cavity{fill:#d3edf4;stroke:#146c91;stroke-dasharray:${4/scale} ${2/scale}}.sensor{fill:#e9deff;stroke:#7355a5}.strap{fill:#eee6da;stroke:#877350}.string{stroke:#777;stroke-width:${1/scale}}</style><rect width="1080" height="950" fill="#fafcfd"/><rect x="20" y="20" width="1040" height="910" fill="none" stroke="#a7b9c0"/>${label(50,57,'ATLAS / '+kit.name,'start')}${label(50,82,(vi?'KÍCH THƯỚC cm · ':'DIMENSIONS cm · ')+view.toUpperCase(),'start')}${grid}<g class="shape" transform="translate(${x} ${y}) scale(${scale})">${body}${rear}</g>${line(x+W/2,y-15,x+W/2,y+H+15,'centre')}${line(x-15,y+H/2,x+W+15,y+H/2,'centre')}${line(x,y-10,x, y-42,'ext')}${line(x+W,y-10,x+W,y-42,'ext')}${line(x,y-30,x+W,y-30)}${label(x+W/2,y-43,cm(w)+' cm')}${line(x-10,y,x-65,y,'ext')}${line(x-10,y+H,x-65,y+H,'ext')}${line(x-52,y,x-52,y+H)}${label(x-64,y+H/2,cm(h)+' cm','end')}${label(x+8,y+H+30,vi?'Gốc O: góc trái trên bao ngoài; X sang phải, Y xuống dưới.':'Origin O: envelope top-left; X right, Y down.','start')}${label(815,135,vi?'CHI TIẾT THAM CHIẾU':'REFERENCE DETAILS')}${label(785,172,'W = '+cm(d.width)+' cm','start')}${label(785,202,'H = '+cm(d.height)+' cm','start')}${label(785,232,'D = '+cm(d.depth)+' cm','start')}${label(785,287,'Core: '+cm(cw)+' × '+cm(ch)+' cm','start')}${label(785,317,'X = '+cm(cx)+'; Y = '+cm(cy)+' cm','start')}${label(785,367,vi?'Liền đậm: biên ngoài':'Solid: outer contour','start')}${label(785,397,vi?'Nét đứt: khoang dự kiến':'Dashed: cavity envelope','start')}${label(785,427,vi?'Gạch chấm: đường tâm':'Chain: centre lines','start')}<rect x="40" y="855" width="1000" height="55" fill="#edf3f6"/>${label(55,878,'REV CAD-01 / '+role.toUpperCase()+' / '+(vi?'KÍCH THƯỚC DỰ KIẾN':'PROVISIONAL DIMENSIONS'),'start')}${label(55,901,vi?'Không đo theo pixel. Đo board, fit người thật và làm carton trước khi cắt EVA.':'Do not measure pixels. Inspect board, fit users and mock up in cardboard before cutting EVA.','start')}</svg>`;
  }
  function render(r=role,l=language,k=kit) {
    role=r; language=l; kit=k; const vi=l==='vi',d=window.ATLAS_PROP_MANIFESTS[r].dimensionsMm,s=specs[r];
    $('cadTitle').textContent=vi?'Bản vẽ kỹ thuật có kích thước · cm':'Dimensioned technical design · cm';
    $('cadViewLabel').textContent=vi?'Mặt nhìn':'View';
    [...$('cadView').options].forEach((o,i)=>o.textContent=(vi?['Mặt trước','Mặt sau / module','Mặt cạnh / bao độ dày']:['Front','Rear / modules','Side / depth envelope'])[i]);
    $('cadGridLabel').textContent=vi?'Lưới 1 cm':'1 cm grid'; $('cadDownload').textContent=vi?'Tải SVG vector':'Download vector SVG';
    $('cadBoundary').textContent=vi?'Bản dự kiến để vẽ mẫu carton, chưa phải CAD sản xuất. Kích thước bao ngoài lấy từ manifest; vị trí core và khoang là đề xuất cần đo board thật. Mặt cạnh là bao độ dày, không phải mặt cắt nội thất.':'A concept sheet for cardboard layout, not manufacturing CAD. Overall dimensions follow the manifest; core/cavity positions need hardware verification. Side view shows the depth envelope, not an internal section.';
    $('cadDrawing').innerHTML=svg();
    const rows=[['W',d.width],['H',d.height],['D',d.depth],['Core X',s.grip[0]],['Core Y',s.grip[1]],['Cavity W',s.cavity[0]],['Cavity H',s.cavity[1]], ...(r==='guardian'?[['Outer R',250],['LED centre R',230],['Inner ring R',220],['Strap width',25],['Strap centre spacing',150],['Face EVA',5],['Ring EVA',10],['Rear EVA',5]]:[])];
    $('cadDimensions').innerHTML=`<table><thead><tr><th>${vi?'Thông số':'Parameter'}</th><th>cm</th><th>mm</th><th>${vi?'Trạng thái':'Status'}</th></tr></thead><tbody>${rows.map(([n,v],i)=>`<tr><td>${n}</td><td>${cm(v)}</td><td>${v}</td><td>${vi?(i<3?'Bao thiết kế':'Đề xuất / cần đo'):(i<3?'Design envelope':'Proposed / measure first')}</td></tr>`).join('')}</tbody></table>`;
    $('cadInstructions').innerHTML=`<h3>${vi?'Vẽ trên carton như thế nào?':'How to mark the cardboard?'}</h3><ol>${(vi?[`Kẻ hình chữ nhật bao ${cm(d.width)} × ${cm(d.height)} cm; đánh dấu gốc O ở góc trái trên.`,`Kẻ lưới cách nhau 1 cm. Kẻ đường tâm ở X = ${cm(d.width/2)} cm và Y = ${cm(d.height/2)} cm.`,`Đánh dấu tâm core ở X = ${cm(s.grip[0])} cm; Y = ${cm(s.grip[1])} cm. Vẽ khoang ${cm(s.cavity[0])} × ${cm(s.cavity[1])} cm bằng nét đứt.`,...s.notes,'Vẽ biên dạng theo SVG, chưa cắt khoang. Đặt board thật và thử cầm/đeo; ghi lại mọi điều chỉnh.']:['Mark the overall rectangle and top-left origin O.','Mark a 1 cm grid and both envelope centre lines.','Mark the core centre and dashed cavity from the table.',...s.en,'Trace the vector contour; do not cut cavities yet. Fit hardware and users, then record changes.']).map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p>${vi?'SVG giữ vector và số đo nhưng không phải mẫu in 1:1. Khi in, dùng kích thước ghi trên bản vẽ để căn tỷ lệ; các mẫu 1:1 đã có vẫn giữ ở phần tải role.':'SVG preserves vectors and dimensions but is not a 1:1 print template. Calibrate print scaling against labelled dimensions; existing role 1:1 templates remain available.'}</p>`;
    if(r==='guardian') $('cadInstructions').innerHTML += `<p>${vi?'Vẽ vòng tròn bằng dây/com-pa: đặt tâm (25; 25) cm, vẽ R25 cm cho mép ngoài, R23 cm cho tâm LED, R22 cm cho biên trong vòng. Tâm quai tại Y17,5 và Y32,5 cm; quai rộng 2,5 cm. Các giá trị quai/khoang cần thử độ vừa, không khoan trước.':'Compass/string layout: centre (25,25) cm; draw R25 outer edge, R23 LED centreline, R22 ring inner edge. Strap centres Y17.5 and Y32.5 cm, width 2.5 cm. Fit-test straps and cavity before drilling.'}</p>`;
    $('cadRenderFigure').hidden=r!=='guardian'; $('cadRenderCaption').textContent=vi?'Ảnh hình thái theo đề bài bản vẽ Guardian Ø50 × 5,5 cm, viền LED và khoang sau. AI có thể khác tỷ lệ quai/khoang: lấy số đo vector, không lấy số đo từ ảnh.':'Appearance concept prompted from the Guardian Ø50 × 5.5 cm design, LED rim and rear cavity. AI may vary strap/cavity proportions: use vector dimensions, never measure the render.';
  }
  $('cadView').addEventListener('change',e=>{view=e.target.value;render();});
  $('cadGrid').addEventListener('change',()=>render());
  $('cadDownload').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([svg()],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download=`atlas-${role}-${view}-cad-01.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);});
  return {render};
})();
